    "img": "https://assets.science.nasa.gov/dynamicimage/assets/science/cds/citizen-science/highlights/2026/cs2_resolution_comparison_Lucy_Fortson.png?w=864&h=279&fit=clip&crop=faces%2Cfocalpoint",
