    "slug": "nasa-testing-wastewater-treatment-facility-for-future-moon-base",
    "cat": "Cosmologia",
    "catCls": "cosmologia",
    "img": "https://images-assets.nasa.gov/image/KSC-20260421-PH-KLS01_0041/KSC-20260421-PH-KLS01_0041~large.jpg?w=1920&h=1280&fit=clip&crop=faces%2Cfocalpoint",
